<?php
namespace App\Console\Commands;use App\Models\{Device,Location};use Illuminate\Console\Command;use Illuminate\Support\Facades\DB;
final class BackfillLocations extends Command{protected $signature='locations:backfill {--dry-run} {--chunk=500}';protected $description='Backfill canonical organization Locations from legacy Device location strings.';public function handle():int{$dry=(bool)$this->option('dry-run');$created=0;$assigned=0;$ambiguous=0;Device::whereNull('location_id')->whereNotNull('location')->where('location','!=','')->orderBy('id')->chunkById((int)$this->option('chunk'),function($devices)use($dry,&$created,&$assigned,&$ambiguous){foreach($devices as$d){$name=trim(preg_replace('/\s+/u',' ',$d->location)??'');if($name==='')continue;$key=mb_strtolower($name,'UTF-8');$matches=Location::where(['organization_id'=>$d->organization_id,'normalized_name'=>$key])->get();if($matches->count()>1){$ambiguous++;continue;}$location=$matches->first();if(!$location&&!$dry){$location=Location::create(['organization_id'=>$d->organization_id,'name'=>$name,'normalized_name'=>$key,'created_by'=>null,'semantic_updated_at'=>null]);$created++;}elseif(!$location)$created++;if(!$dry&&$location)DB::table('devices')->where('id',$d->id)->whereNull('location_id')->update(['location_id'=>$location->id]);$assigned++;}});$this->info("created={$created} assigned={$assigned} ambiguous={$ambiguous} dry_run=".($dry?'yes':'no'));return $ambiguous?self::FAILURE:self::SUCCESS;}}